from dataclasses import dataclass

@dataclass(frozen=True)
class Skill:
    id: str
    name: str
    description: str
    instruction: str

SKILLS = [
    Skill("legal_notice", "Legal notice", "Formal notice, facts, demand and deadline.",
         "Draft a formal legal notice. Structure it with parties, verified facts, legal basis only where supplied or verified, demand, deadline, and reservation of rights. Mark missing information with placeholders."),
    Skill("contract", "Contract drafting", "Build a structured agreement and flag missing terms.",
         "Draft a contract with parties, definitions, scope, obligations, payment, term, termination, confidentiality, liability, dispute resolution, governing law, and signatures as relevant. Flag missing commercial terms."),
    Skill("agreement", "Agreement", "Clear terms, obligations and execution blocks.",
         "Draft a clear agreement with recitals, definitions where needed, operative clauses, obligations, conditions, term, termination, dispute resolution and execution blocks."),
    Skill("petition", "Petition / application", "Facts, grounds, jurisdiction and relief sought.",
         "Prepare a structured petition/application with forum, parties, jurisdiction, material facts, grounds, relief sought, interim relief if requested, and verification. Flag procedural requirements needing counsel review."),
    Skill("clause_review", "Clause review", "Identify ambiguity, gaps and negotiation points.",
         "Review the supplied clause for ambiguity, imbalance, missing definitions, conflicting obligations, unclear remedies, and negotiation points. Quote the relevant text, explain the issue, and suggest wording."),
    Skill("redline_review", "Redline-style review", "Compare original wording with proposed changes.",
         "Compare the supplied text against the requested position. Provide a change table with original wording, proposed wording, and reason. Do not claim tracked changes were created."),
    Skill("legal_research", "Legal research brief", "Separate research questions, findings and unknowns.",
         "Prepare a research brief with questions, issues, search terms, source-backed findings, counterpoints and unresolved questions. Never invent authorities; clearly distinguish provided sources from hypotheses."),
    Skill("case_analysis", "Case analysis", "Facts, issues, reasoning and outcome.",
         "Analyze only the case facts and judgment text supplied. Separate facts, issues, reasoning, outcome, implications, and open questions. State when the judgment text or reliable source is missing."),
    Skill("due_diligence", "Due diligence", "Evidence-led checklist and risk register.",
         "Create a due-diligence table with document, issue, risk level, evidence, missing information, and follow-up. Do not infer that absent documents do not exist."),
    Skill("summarize", "Document summary", "Preserve obligations, dates and exceptions.",
         "Summarize the supplied material faithfully. Preserve parties, dates, obligations, exceptions, defined terms and citations. Distinguish source text from inference.")
]

